cd .. && python3 -I - <<'EOF'
import csv, json
S="/tmp/claude-1000/REDACTED/a8a923ef-f5a7-45c6-9846-733930fb99a7/scratchpad/simresults.jsonl"
rows=[json.loads(l) for l in open(S)]
label={"confident":("v8 - alex","Confident (smart + confidence index)","confidence index drives step, early accept, tone; never fired on the simulator (no floor signals), gain is from holding firmer"),
       "confident_boulware":("v9 - alex","Confident Turtle (boulware + confidence index)","Iron Turtle with confidence bending time (t_eff = 1-(1-t)*conf) and early accept at conf<=0.25; identical to v6 on the simulator because conf stays 1.0"),
       "confident_router":("v10 - alex","Confident Owl (router: leverage->confident_boulware, routine->rational)","S01/S02 leverage -> Confident Turtle, S03 routine -> Patient Hawk; best combined simulator result"),
       "rational":("v2.1 - alex","Patient Hawk (rational, game theory)","rerun of Niko's v2.1 after merge; replaces the shifted v2/v2.1 rows which are unreadable")}
def terms(r):
    t=r.get("terms") or {}
    bits=[f"unit_price {t['unit_price']}"] if t.get("unit_price") else []
    for k in ("payment_days","contract_months","incoterm","lead_time_days"):
        if t.get(k) is not None: bits.append(f"{k} {t[k]}")
    return ", ".join(bits)
with open("backlog.csv","a",newline="") as f:
    w=csv.writer(f, lineterminator="\n")
    for key in ("rational","confident","confident_boulware","confident_router"):
        for r in rows:
            if r["agent"]!=key or "error" in r: continue
            ver,agent,note=label[key]
            w.writerow(["2026-10-10",ver,agent,"simulator",r["case"],"yes" if r.get("deal") else "no",
                        f"{r['c_open']:.2f}",f"{r['c_deal']:.2f}",f"{r['c_best']:.2f}",f"{r['score']:.2f}",r["replay"],f"{terms(r)}; {note}"])
print(open("backlog.csv").read().count("\n"), "lines now")
EOF
tail -3 backlog.csv | cut -c1-160; python3 -I -c "import csv;rows=list(csv.reader(open('backlog.csv')));bad=[i for i,r in enumerate(rows) if len(r)!=12];print('rows with wrong column count:',bad)"

